// ============================================================
// LOCALE LOADING
// ============================================================

/**
 * Synchronously load a JSON locale file for the given language code.
 * Falls back to English if the requested locale cannot be loaded.
 *
 * @param {string} lang - Language code (e.g. 'en', 'ru')
 * @returns {Object<string, string>} Parsed locale dictionary
 */
function loadLocale(lang) {
  if (Object.prototype.hasOwnProperty.call(_i18nEmbeddedLocales, lang)) {
    return Object.assign({}, _i18nEmbeddedLocales[lang]);
  }

  const url = 'app/locales/' + lang + '.json';
  try {
    const xhr = new XMLHttpRequest();
    xhr.open('GET', url, false); // synchronous
    xhr.send(null);

    if (xhr.status === 200 || xhr.status === 0) {
      return JSON.parse(xhr.responseText);
    }
  } catch (e) {
    console.warn('[i18n] Failed to load locale "' + lang + '":', e);
  }

  // Fall back to English when the requested locale is unavailable
  if (lang !== 'en') {
    console.warn('[i18n] Falling back to English.');
    return loadLocale('en');
  }

  // If even English fails, return an empty dictionary
  return {};
}

// ============================================================
// TRANSLATION FUNCTION
// ============================================================

/**
 * Look up a translation key in the current locale dictionary.
 * If the key is missing the key itself is returned unchanged.
 * Optional `params` object replaces `{name}` placeholders.
 *
 * @param {string} key   - Flat translation key
 * @param {Object<string, string>} [params] - Interpolation values
 * @returns {string} Translated (and interpolated) string
 */
function t(key, params) {
  let value = (_i18nLocale && Object.prototype.hasOwnProperty.call(_i18nLocale, key))
    ? _i18nLocale[key]
    : key;

  if (params && typeof params === 'object') {
    const keys = Object.keys(params);
    for (let i = 0; i < keys.length; i++) {
      value = value.replace(new RegExp('\\{' + keys[i] + '\\}', 'g'), params[keys[i]]);
    }
  }

  return value;
}

/**
 * Lazily load and cache the English locale for reverse lookups.
 *
 * @returns {Object<string, string>}
 */
function getEnglishLocale() {
  if (_i18nEnglishLocale) {
    return _i18nEnglishLocale;
  }

  if (_i18nCurrentLang === 'en' && _i18nLocale) {
    _i18nEnglishLocale = _i18nLocale;
    return _i18nEnglishLocale;
  }

  _i18nEnglishLocale = loadLocale('en');
  return _i18nEnglishLocale;
}

/**
 * Build reverse map: English text value -> translation keys.
 *
 * @returns {Object<string, Array<string>>}
 */
function getEnglishReverseMap() {
  if (_i18nEnglishReverseMap) {
    return _i18nEnglishReverseMap;
  }

  const locale = getEnglishLocale();
  const reverse = {};
  const keys = Object.keys(locale);

  for (let i = 0; i < keys.length; i++) {
    const key = keys[i];
    const value = locale[key];
    if (typeof value !== 'string' || !value) continue;
    if (!reverse[value]) reverse[value] = [];
    reverse[value].push(key);
  }

  _i18nEnglishReverseMap = reverse;
  return _i18nEnglishReverseMap;
}

/**
 * Pick the most suitable translation key among candidates.
 *
 * @param {Array<string>} keys
 * @param {'text'|'title'|'aria'|'placeholder'} context
 * @returns {string|null}
 */
function pickBestKey(keys, context) {
  if (!Array.isArray(keys) || keys.length === 0) return null;
  if (keys.length === 1) return keys[0];

  const sorted = keys.slice().sort();
  const contains = function contains(fragment) {
    return sorted.find(k => k.indexOf(fragment) !== -1) || null;
  };

  if (context === 'title') {
    return contains('_title') || contains('.title') || sorted[0];
  }
  if (context === 'aria') {
    return contains('_aria') || contains('.aria') || sorted[0];
  }
  if (context === 'placeholder') {
    return contains('placeholder') || sorted[0];
  }

  const nonMeta = sorted.find(k => (
    k.indexOf('_title') === -1
    && k.indexOf('_aria') === -1
    && k.indexOf('placeholder') === -1
  ));
  return nonMeta || sorted[0];
}

/**
 * Translate text when the source string is an English locale value.
 * Useful for legacy static UI strings that still do not have data-i18n attributes.
 *
 * @param {string} sourceText
 * @param {'text'|'title'|'aria'|'placeholder'} [context]
 * @returns {string}
 */
function translateLiteral(sourceText, context) {
  if (typeof sourceText !== 'string' || !sourceText) return sourceText;
  const reverse = getEnglishReverseMap();
  const candidates = reverse[sourceText];
  const key = pickBestKey(candidates, context || 'text');
  if (!key) return sourceText;
  return t(key);
}

/**
 * Look up the best translation key for a given English text value.
 * Returns the key string if found, or null if no match exists.
 *
 * @param {string} sourceText - English text to look up
 * @param {'text'|'title'|'aria'|'placeholder'} [context]
 * @returns {string|null}
 */
function lookupKey(sourceText, context) {
  if (typeof sourceText !== 'string' || !sourceText) return null;
  const reverse = getEnglishReverseMap();
  const candidates = reverse[sourceText];
  return pickBestKey(candidates, context || 'text');
}

// ============================================================
// DOM TRANSLATION
// ============================================================

/**
 * Walk the DOM and apply translations to every element that carries
 * a `data-i18n*` attribute.
 *
 * Supported attributes:
 *   data-i18n              → textContent
 *   data-i18n-title        → title
 *   data-i18n-placeholder  → placeholder
 *   data-i18n-aria-label   → aria-label
 *   data-i18n-html         → innerHTML (locale files must be trusted sources)
 */
function applyTranslations() {
  // textContent
  const textEls = document.querySelectorAll('[data-i18n]');
  for (let i = 0; i < textEls.length; i++) {
    textEls[i].textContent = t(textEls[i].getAttribute('data-i18n'));
  }

  // title attribute
  const titleEls = document.querySelectorAll('[data-i18n-title]');
  for (let i = 0; i < titleEls.length; i++) {
    titleEls[i].title = t(titleEls[i].getAttribute('data-i18n-title'));
  }

  // placeholder attribute
  const placeholderEls = document.querySelectorAll('[data-i18n-placeholder]');
  for (let i = 0; i < placeholderEls.length; i++) {
    placeholderEls[i].placeholder = t(placeholderEls[i].getAttribute('data-i18n-placeholder'));
  }

  // data-tooltip attribute
  const tooltipEls = document.querySelectorAll('[data-i18n-tooltip]');
  for (let i = 0; i < tooltipEls.length; i++) {
    tooltipEls[i].setAttribute('data-tooltip', t(tooltipEls[i].getAttribute('data-i18n-tooltip')));
  }

  // aria-label attribute
  const ariaEls = document.querySelectorAll('[data-i18n-aria-label]');
  for (let i = 0; i < ariaEls.length; i++) {
    ariaEls[i].setAttribute('aria-label', t(ariaEls[i].getAttribute('data-i18n-aria-label')));
  }

  // innerHTML – safe because locale files are local trusted sources
  const htmlEls = document.querySelectorAll('[data-i18n-html]');
  for (let i = 0; i < htmlEls.length; i++) {
    htmlEls[i].innerHTML = t(htmlEls[i].getAttribute('data-i18n-html'));
  }

  // Legacy fallback translation: translate static attributes/text that
  // still use English literals but have equivalent entries in locale files.
  const excludedContainerSelector = '[contenteditable="true"], #mainEditor, #headerEditor, #footerEditor';
  const shouldSkip = function shouldSkip(el) {
    return !!el.closest(excludedContainerSelector);
  };

  const titleFallbackEls = document.querySelectorAll('[title]:not([data-i18n-title])');
  for (let i = 0; i < titleFallbackEls.length; i++) {
    const el = titleFallbackEls[i];
    if (shouldSkip(el)) continue;
    const value = el.getAttribute('title');
    const key = lookupKey(value, 'title');
    if (key) {
      el.setAttribute('data-i18n-title', key);
      el.setAttribute('title', t(key));
    }
  }

  const ariaFallbackEls = document.querySelectorAll('[aria-label]:not([data-i18n-aria-label])');
  for (let i = 0; i < ariaFallbackEls.length; i++) {
    const el = ariaFallbackEls[i];
    if (shouldSkip(el)) continue;
    const value = el.getAttribute('aria-label');
    const key = lookupKey(value, 'aria');
    if (key) {
      el.setAttribute('data-i18n-aria-label', key);
      el.setAttribute('aria-label', t(key));
    }
  }

  const placeholderFallbackEls = document.querySelectorAll('[placeholder]:not([data-i18n-placeholder])');
  for (let i = 0; i < placeholderFallbackEls.length; i++) {
    const el = placeholderFallbackEls[i];
    if (shouldSkip(el)) continue;
    const value = el.getAttribute('placeholder');
    const key = lookupKey(value, 'placeholder');
    if (key) {
      el.setAttribute('data-i18n-placeholder', key);
      el.setAttribute('placeholder', t(key));
    }
  }

  const textFallbackEls = document.querySelectorAll('button, label, option, span, p, h2, h3, h4, h5, h6, legend, summary');
  for (let i = 0; i < textFallbackEls.length; i++) {
    const el = textFallbackEls[i];
    if (el.hasAttribute('data-i18n') || shouldSkip(el)) continue;
    if (el.childNodes.length !== 1 || el.childNodes[0].nodeType !== Node.TEXT_NODE) continue;

    const value = el.textContent.trim();
    if (!value) continue;

    const key = lookupKey(value, 'text');
    if (key) {
      el.setAttribute('data-i18n', key);
      el.textContent = t(key);
    }
  }
}

// ============================================================
// LANGUAGE SWITCHING
// ============================================================

/**
 * Switch the active language.
 * Loads the locale file, applies translations, persists the choice
 * in localStorage and updates the document lang attribute.
 *
 * @param {string} lang - Language code to switch to
 */
function setLanguage(lang) {
  const isSupported = _i18nAvailableLanguages.some(item => item.code === lang);
  if (!isSupported) {
    lang = 'en';
  }

  _i18nLocale = loadLocale(lang);
  _i18nCurrentLang = lang;

  applyTranslations();

  const languageSwitcher = document.getElementById('languageSwitcher');
  if (languageSwitcher) {
    languageSwitcher.value = lang;
  }

  try {
    localStorage.setItem(I18N_STORAGE_KEY, lang);
  } catch (e) {
    console.warn('[i18n] Could not persist language preference:', e);
  }

  document.documentElement.lang = lang;
}

// ============================================================
// QUERIES
// ============================================================

/**
 * Return the current active language code.
 *
 * @returns {string} Language code (e.g. 'en')
 */
function getCurrentLanguage() {
  return _i18nCurrentLang;
}

/**
 * Return the list of available languages.
 *
 * @returns {Array<{code: string, name: string}>}
 */
function getAvailableLanguages() {
  return _i18nAvailableLanguages;
}

window.i18n = window.i18n || {};
window.i18n.translateLiteral = translateLiteral;

// ============================================================
// INITIALIZATION
// ============================================================

/**
 * Early locale bootstrap – runs immediately so that `t()` returns correct
 * translations even when other scripts call it at parse time (before
 * DOMContentLoaded).  Only DOM-dependent work (applying translations to
 * elements, attaching the language-switcher listener) is deferred.
 */
(function bootstrapLocale() {
  var lang = 'en';
  try {
    var stored = localStorage.getItem(I18N_STORAGE_KEY);
    if (stored && _i18nAvailableLanguages.some(function (item) { return item.code === stored; })) {
      lang = stored;
    }
  } catch (e) {
    // localStorage may be unavailable – default to English
  }

  _i18nLocale = loadLocale(lang);
  _i18nCurrentLang = lang;
  document.documentElement.lang = lang;
})();

/**
 * Finish initialization once the DOM is ready: apply translations to all
 * marked elements, wire up the language-switcher dropdown, and persist the
 * user's choice.
 */
function initI18nDOM() {
  applyTranslations();

  var languageSwitcher = document.getElementById('languageSwitcher');
  if (languageSwitcher) {
    languageSwitcher.value = _i18nCurrentLang;
    languageSwitcher.addEventListener('change', function onLanguageChange(e) {
      setLanguage(e.target.value);
    });
  }

  try {
    localStorage.setItem(I18N_STORAGE_KEY, _i18nCurrentLang);
  } catch (e) {
    // Ignore – persistence is best-effort
  }
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initI18nDOM);
} else {
  initI18nDOM();
}
